import { defineConfig, type Connect, type Plugin } from 'vite';
import { createReadStream, existsSync, statSync } from 'node:fs';
import path from 'node:path';

// Terrain tiles (hundreds of MB, generated by scripts/build-terrain.ts) live in
// ./terrain instead of ./public, so `vite build` doesn't copy them into dist.
// In dev/preview they are served under /terrain/.
const TERRAIN_DIR = path.resolve(import.meta.dirname, 'terrain');
const TYPES: Record<string, string> = { '.json': 'application/json', '.webp': 'image/webp', '.png': 'image/png' };

function serveTerrain(): Plugin {
  const middleware: Connect.NextHandleFunction = (req, res, next) => {
    if (!req.url?.startsWith('/terrain/')) return next();
    const rel = decodeURIComponent(req.url.split('?')[0].slice('/terrain/'.length));
    const file = path.resolve(TERRAIN_DIR, rel);
    if (!file.startsWith(TERRAIN_DIR + path.sep) || !existsSync(file) || !statSync(file).isFile()) {
      res.statusCode = 404;
      res.end();
      return;
    }
    res.setHeader('Content-Type', TYPES[path.extname(file)] ?? 'application/octet-stream');
    res.setHeader('Cache-Control', file.endsWith('.json') ? 'no-cache' : 'max-age=3600');
    createReadStream(file).pipe(res);
  };
  return {
    name: 'serve-terrain',
    configureServer: (server) => void server.middlewares.use(middleware),
    configurePreviewServer: (server) => void server.middlewares.use(middleware),
  };
}

export default defineConfig({
  plugins: [serveTerrain()],
});
